import { Component, OnInit } from '@angular/core';
import { MisCompras } from 'src/app/models/mis-compras';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';
import { Subscription } from 'rxjs';
@Component({
  selector: 'app-compras-de-un-usuario',
  templateUrl: './compras-de-un-usuario.component.html',
  styleUrls: ['./compras-de-un-usuario.component.css']
})
export class ComprasDeUnUsuarioComponent {

  contarCompra: number = 0;
  private emailSubscription: Subscription;

  constructor(private usuarioService: UsuarioService, private misComprasService: MisComprasService) {}

  ngOnInit() {
    this.emailSubscription = this.usuarioService.getEmailUsuarioLogeado().subscribe(email => {
      if (email && email !== "null") {
        this.cargarCompras(email);
      } else {
        this.contarCompra = 0;
      }
    });
  }

  ngOnDestroy() {
    this.emailSubscription.unsubscribe();
  }

  cargarCompras(email: string) {
    this.misComprasService.obtenerComprasUsuario(email).subscribe(
      (res: any) => {
        this.contarCompra = res.length;
      },
      error => console.error('Error al obtener las compras del usuario', error)
    );
  }

}
